mapper.insert:
MERGE INTO TB_PERMISSION P USING ( SELECT (SELECT NVL(MAX(PERM_ID), 0) FROM TB_PERMISSION) + ROW_NUMBER() OVER (ORDER BY PERM_CD) AS PERM_ID, PERM_CD, PERM_NM, PERM_EXPLN, 'Y' AS PERM_ENABLED FROM (
SELECT #{permission.code} AS PERM_CD, #{permission.name} AS PERM_NM, #{permission.description} AS PERM_EXPLN FROM DUAL
) ) SRC ON (P.PERM_CD = SRC.PERM_CD) WHEN NOT MATCHED THEN INSERT ( PERM_ID, PERM_CD, PERM_NM, PERM_EXPLN, PERM_ENABLED ) VALUES ( SRC.PERM_ID, SRC.PERM_CD, SRC.PERM_NM, SRC.PERM_EXPLN, SRC.PERM_ENABLED )
